function features = fun_simulation_blood_flow_compute_network_features(vessel_graph, voxel_size)
% fun_simulation_blood_flow_compute_network_features computes network
% features required for blood flow simulation
% Input: 
%   vessel_graph: structure, generated by fun_skeleton_to_graph, with extra
%   field added by fun_graph_add_radius and fun_graph_add_voxel_label
%   voxel_size; numerical scalar, size of the voxel in the image from which
%   the graph is computed. Currently, only isotropic voxel size is
%   supported. Express the value in SI unit. 
% Output: 
%   vessel_graph: structure with additional fields that are necessary for
%   blood flow simulation in the network
% 
% Implemented by Xiang Ji on 07/24/2019

if nargin < 2
    voxel_size = 10^-6; % meter, assume isotropic voxel size
end
if isfield(vessel_graph, 'label')
    has_vessel_type_label_Q = true;
    [features.radius, features.type, features.length] ...
    = deal(nan(size(vessel_graph.link.num_voxel_per_cc)));
else
    has_vessel_type_label_Q = false;
        [features.radius, features.length] ...
    = deal(nan(size(vessel_graph.link.num_voxel_per_cc)));
end
for iter_link = 1 : vessel_graph.link.num_cc
    tmp_ind = vessel_graph.link.cc_ind{iter_link};
    tmp_r = full(vessel_graph.radius(tmp_ind));
    if any(tmp_r == 0)
        error('Link voxel radius is 0');
    end
    features.radius(iter_link) = median(tmp_r);
    % Link type: capillary, artery or vein
    if has_vessel_type_label_Q
        tmp_label = unique(full(vessel_graph.label(tmp_ind)));
        if ~isscalar(tmp_label)
           fprintf('The link has mixed voxel label\n');
           % Check if more than 1 label is greater than 1
           tmp_label = tmp_label(tmp_label > 1);
           assert(isscalar(tmp_label), 'The link contians voxel labeled as artery and vein');
        end
        features.type(iter_link) = tmp_label;
    end
    % Length
    features.length(iter_link) = fun_graph_sub_to_length(...
        fun_ind2sub(vessel_graph.num.mask_size, tmp_ind), voxel_size);
end
% Convert all the number to SI unit
features.radius = features.radius .* voxel_size;
features.cross_section_area = pi * features.radius .^ 2;

features.resistance = fun_simulation_blood_flow_get_vessel_resistance(...
    features.radius, features.length, 'm');
features.conductance = 1 ./ features.resistance;
end